{"task": "Find all Java stack trace lines in log messages", "sql": "SELECT * FROM logs WHERE regexp_like(message, '^java\\.lang\\.[A-Z][a-z]+:')"}
{"task": "Identify Python exception traces with traceback information", "sql": "SELECT * FROM logs WHERE regexp_like(message, 'Traceback \\(most recent call last\\):')"}
{"task": "Extract log lines containing Java class loading errors", "sql": "SELECT * FROM logs WHERE regexp_like(message, 'Caused by: java\\.lang\\.ClassNotFoundException')"}
{"task": "Filter for Python syntax error messages", "sql": "SELECT * FROM logs WHERE regexp_like(message, 'SyntaxError:')"}
{"task": "Find all log entries with Java thread dump patterns", "sql": "SELECT * FROM logs WHERE regexp_like(message, '^\".*\" (tid=0x[0-9a-f]+) prio=.*java\\.lang\\.Thread\\$State')"}
{"task": "Identify Python import errors in application logs", "sql": "SELECT * FROM logs WHERE regexp_like(message, 'ImportError:')"}
{"task": "Extract lines with Java OutOfMemoryError patterns", "sql": "SELECT * FROM logs WHERE regexp_like(message, 'java\\.lang\\.OutOfMemoryError')"}
{"task": "Find Python unhandled exception traces", "sql": "SELECT * FROM logs WHERE regexp_like(message, 'Unhandled exception:') OR regexp_like(message, 'Exception in thread.*')
{"task": "Identify Java NullPointerException messages with stack traces", "sql": "SELECT * FROM logs WHERE regexp_like(message, '^java\\.lang\\.NullPointerException')"}
{"task": "Filter log lines for Python RuntimeError exceptions", "sql": "SELECT * FROM logs WHERE regexp_like(message, 'RuntimeError:') AND level = 'ERROR'"}

